#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

template <typename T>
class KernelMaskedSoftmaxWithRelPosBias {
public:
    __aicore__ inline KernelMaskedSoftmaxWithRelPosBias() {}

    __aicore__ inline void Init(
        GM_ADDR x,
        GM_ADDR attenMask,
        GM_ADDR relPosBias,
        GM_ADDR out,
        GM_ADDR tilingData,
        AscendC::TPipe *pipe)
    {
        // Copy tiling data
        AscendC::GlobalTensor<int64_t> tilingGm;
        tilingGm.SetGlobalBuffer(reinterpret_cast<__gm__ int64_t *>(tilingData), 16);
        AscendC::DataCopy(tiling_, tilingGm, 16);

        totalRows_ = tiling_.totalRows;
        rowLength_ = tiling_.rowLength;
        hasAttenMask_ = tiling_.hasAttenMask;
        scaleValue_ = tiling_.scaleValue;
        formerNum_ = tiling_.formerNum;
        formerLength_ = tiling_.formerLength;
        tailNum_ = tiling_.tailNum;
        tailLength_ = tiling_.tailLength;
        tileLength_ = tiling_.tileLength;
        blockRows_ = tiling_.blockRows;

        // Bind GM tensors
        xGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(x), totalRows_ * rowLength_);
        outGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(out), totalRows_ * rowLength_);
        if (hasAttenMask_ == 1) {
            attenMaskGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(attenMask), totalRows_ * rowLength_);
        }
        relPosBiasGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(relPosBias), totalRows_ * rowLength_);

        // Initialize queues
        pipe->InitBuffer(xQueue_, BUFFER_NUM, tileLength_ * sizeof(T));
        pipe->InitBuffer(outQueue_, BUFFER_NUM, tileLength_ * sizeof(T));
        pipe->InitBuffer(biasQueue_, BUFFER_NUM, tileLength_ * sizeof(T));
        if (hasAttenMask_ == 1) {
            pipe->InitBuffer(maskQueue_, BUFFER_NUM, tileLength_ * sizeof(T));
        }

        // TBuf for FP32 computation
        uint32_t fp32BufSize = tileLength_ * sizeof(float);
        pipe->InitBuffer(tmpFp32Buf_, fp32BufSize);
        pipe->InitBuffer(maxBuf_, blockRows_ * sizeof(float));
        pipe->InitBuffer(sumBuf_, blockRows_ * sizeof(float));
        pipe->InitBuffer(reduceTmpBuf_, 2 * tileLength_ * sizeof(uint8_t));
    }

    __aicore__ inline void Process()
    {
        int64_t coreIdx = AscendC::GetBlockIdx();
        int64_t coreNum = AscendC::GetBlockNum();

        for (int64_t i = coreIdx; i < formerNum_; i += coreNum) {
            int64_t rowOffset = i * formerLength_;
            int64_t curTileLength = formerLength_;
            CopyIn(rowOffset, curTileLength, 0);
            Compute(curTileLength, 0);
            CopyOut(rowOffset, curTileLength, 0);
        }

        for (int64_t i = coreIdx; i < tailNum_; i += coreNum) {
            int64_t rowOffset = formerNum_ * formerLength_ + i * tailLength_;
            int64_t curTileLength = tailLength_;
            CopyIn(rowOffset, curTileLength, 1);
            Compute(curTileLength, 1);
            CopyOut(rowOffset, curTileLength, 1);
        }
    }

private:
    __aicore__ inline void CopyIn(int64_t rowOffset, int64_t curTileLength, int32_t progress)
    {
        AscendC::LocalTensor<T> xLocal = xQueue_.AllocTensor<T>();
        AscendC::LocalTensor<T> biasLocal = biasQueue_.AllocTensor<T>();

        AscendC::DataCopyPad(xLocal, xGm_[rowOffset * rowLength_],
            AscendC::DataCopyParams{1, static_cast<uint16_t>(curTileLength * sizeof(T)), 0, 0},
            AscendC::DataCopyPadExtParams<T>{false, 0, 0, 0});
        xQueue_.EnQue(xLocal);

        AscendC::DataCopyPad(biasLocal, relPosBiasGm_[rowOffset * rowLength_],
            AscendC::DataCopyParams{1, static_cast<uint16_t>(curTileLength * sizeof(T)), 0, 0},
            AscendC::DataCopyPadExtParams<T>{false, 0, 0, 0});
        biasQueue_.EnQue(biasLocal);

        if (hasAttenMask_ == 1) {
            AscendC::LocalTensor<T> maskLocal = maskQueue_.AllocTensor<T>();
            AscendC::DataCopyPad(maskLocal, attenMaskGm_[rowOffset * rowLength_],
                AscendC::DataCopyParams{1, static_cast<uint16_t>(curTileLength * sizeof(T)), 0, 0},
                AscendC::DataCopyPadExtParams<T>{false, 0, 0, 0});
            maskQueue_.EnQue(maskLocal);
        }
    }

    __aicore__ inline void Compute(int64_t curTileLength, int32_t progress)
    {
        AscendC::LocalTensor<T> xLocal = xQueue_.DeQue<T>();
        AscendC::LocalTensor<T> biasLocal = biasQueue_.DeQue<T>();
        AscendC::LocalTensor<T> outLocal = outQueue_.AllocTensor<T>();
        AscendC::LocalTensor<float> tmpFp32 = tmpFp32Buf_.Get<float>();
        AscendC::LocalTensor<float> maxLocal = maxBuf_.Get<float>();
        AscendC::LocalTensor<float> sumLocal = sumBuf_.Get<float>();
        AscendC::LocalTensor<uint8_t> reduceTmp = reduceTmpBuf_.Get<uint8_t>();

        int64_t curBlockRows = curTileLength / rowLength_;
        if (curTileLength % rowLength_ != 0) {
            curBlockRows += 1;
        }

        // Cast input to FP32
        if constexpr (sizeof(T) == sizeof(half)) {
            AscendC::Cast(tmpFp32, xLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
        } else if constexpr (sizeof(T) == sizeof(float)) {
            AscendC::DataCopy(tmpFp32, reinterpret_cast<AscendC::LocalTensor<float>&>(xLocal), curTileLength);
        } else {
            // bfloat16
            AscendC::Cast(tmpFp32, xLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
        }

        // Multiply by scale
        AscendC::Muls(tmpFp32, tmpFp32, scaleValue_, curTileLength);

        // Cast bias to FP32 and add
        AscendC::LocalTensor<float> biasFp32 = tmpFp32Buf_.Get<float>();
        if constexpr (sizeof(T) == sizeof(half)) {
            AscendC::Cast(biasFp32, biasLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
        } else if constexpr (sizeof(T) == sizeof(float)) {
            AscendC::DataCopy(biasFp32, reinterpret_cast<AscendC::LocalTensor<float>&>(biasLocal), curTileLength);
        } else {
            AscendC::Cast(biasFp32, biasLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
        }
        AscendC::Add(tmpFp32, tmpFp32, biasFp32, curTileLength);

        // Add atten_mask if present
        if (hasAttenMask_ == 1) {
            AscendC::LocalTensor<T> maskLocal = maskQueue_.DeQue<T>();
            AscendC::LocalTensor<float> maskFp32 = tmpFp32Buf_.Get<float>();
            if constexpr (sizeof(T) == sizeof(half)) {
                AscendC::Cast(maskFp32, maskLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
            } else if constexpr (sizeof(T) == sizeof(float)) {
                AscendC::DataCopy(maskFp32, reinterpret_cast<AscendC::LocalTensor<float>&>(maskLocal), curTileLength);
            } else {
                AscendC::Cast(maskFp32, maskLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
            }
            AscendC::Add(tmpFp32, tmpFp32, maskFp32, curTileLength);
            maskQueue_.FreeTensor(maskLocal);
        }

        // Softmax: find max per row
        for (int64_t r = 0; r < curBlockRows; r++) {
            int64_t rowStart = r * rowLength_;
            int64_t rowLen = (rowStart + rowLength_ <= curTileLength) ? rowLength_ : (curTileLength - rowStart);
            if (rowLen > 0) {
                AscendC::LocalTensor<float> rowData = tmpFp32.GetValue(rowStart);
                AscendC::LocalTensor<float> rowMax = maxLocal.GetValue(r);
                // Use WholeReduceMax for row max
                AscendC::WholeReduceMax(rowMax, rowData, rowLen, 1, 8, 0);
            }
        }

        // Subtract max and exp
        for (int64_t r = 0; r < curBlockRows; r++) {
            int64_t rowStart = r * rowLength_;
            int64_t rowLen = (rowStart + rowLength_ <= curTileLength) ? rowLength_ : (curTileLength - rowStart);
            if (rowLen > 0) {
                AscendC::LocalTensor<float> rowData = tmpFp32.GetValue(rowStart);
                // Subtract max (broadcast)
                AscendC::LocalTensor<float> maxVal = maxLocal.GetValue(r);
                AscendC::LocalTensor<float> maxBroadcast = tmpFp32Buf_.Get<float>();
                for (int64_t c = 0; c < rowLen; c++) {
                    maxBroadcast.SetValue(c, maxVal.GetValue(0));
                }
                AscendC::Sub(rowData, rowData, maxBroadcast, rowLen);
                // Exp
                AscendC::Exp(rowData, rowData, rowLen);
            }
        }

        // Sum per row
        for (int64_t r = 0; r < curBlockRows; r++) {
            int64_t rowStart = r * rowLength_;
            int64_t rowLen = (rowStart + rowLength_ <= curTileLength) ? rowLength_ : (curTileLength - rowStart);
            if (rowLen > 0) {
                AscendC::LocalTensor<float> rowData = tmpFp32.GetValue(rowStart);
                AscendC::LocalTensor<float> rowSum = sumLocal.GetValue(r);
                AscendC::WholeReduceSum(rowSum, rowData, rowLen, 1, 8, 0);
            }
        }

        // Divide by sum
        for (int64_t r = 0; r < curBlockRows; r++) {
            int64_t rowStart = r * rowLength_;
            int64_t rowLen = (rowStart + rowLength_ <= curTileLength) ? rowLength_ : (curTileLength - rowStart);
            if (rowLen > 0) {
                AscendC::LocalTensor<float> rowData = tmpFp32.GetValue(rowStart);
                AscendC::LocalTensor<float> sumVal = sumLocal.GetValue(r);
                AscendC::LocalTensor<float> sumBroadcast = tmpFp32Buf_.Get<float>();
                for (int64_t c = 0; c < rowLen; c++) {
                    sumBroadcast.SetValue(c, sumVal.GetValue(0));
                }
                AscendC::Div(rowData, rowData, sumBroadcast, rowLen);
            }
        }

        // Cast back to output dtype
        if constexpr (sizeof(T) == sizeof(half)) {
            AscendC::Cast(outLocal, tmpFp32, AscendC::RoundMode::CAST_ROUND, curTileLength);
        } else if constexpr (sizeof(T) == sizeof(float)) {
            AscendC::DataCopy(reinterpret_cast<AscendC::LocalTensor<float>&>(outLocal), tmpFp32, curTileLength);
        } else {
            AscendC::Cast(outLocal, tmpFp32, AscendC::RoundMode::CAST_ROUND, curTileLength);
        }

        outQueue_.EnQue(outLocal);
        xQueue_.FreeTensor(xLocal);
        biasQueue_.FreeTensor(biasLocal);
    }

    __aicore__ inline void CopyOut(int64_t rowOffset, int64_t curTileLength, int32_t progress)
    {
        AscendC::LocalTensor<T> outLocal = outQueue_.DeQue<T>();
        AscendC::DataCopyPad(outGm_[rowOffset * rowLength_], outLocal,
            AscendC::DataCopyParams{1, static_cast<uint16_t>(curTileLength * sizeof(T)), 0, 0},
            AscendC::DataCopyPadExtParams<T>{false, 0, 0, 0});
        outQueue_.FreeTensor(outLocal);
    }

private:
    // Tiling data
    struct TilingData {
        int64_t totalRows;
        int64_t rowLength;
        int64_t hasAttenMask;
        float scaleValue;
        int64_t formerNum;
        int64_t formerLength;
        int64_t tailNum;
        int64_t tailLength;
        int64_t tileLength;
        int64_t blockRows;
    } tiling_;

    int64_t totalRows_;
    int64_t rowLength_;
    int64_t hasAttenMask_;
    float scaleValue_;
    int64_t formerNum_;
    int64_t formerLength_;
    int64_t tailNum_;
    int64_t tailLength_;
    int64_t tileLength_;
    int64_t blockRows_;

    // GM tensors
    AscendC::GlobalTensor<T> xGm_;
    AscendC::GlobalTensor<T> attenMaskGm_;
    AscendC::GlobalTensor<T> relPosBiasGm_;
    AscendC::GlobalTensor<T> outGm_;

    // Queues
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> biasQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> maskQueue_;

    // Buffers
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpFp32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> maxBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceTmpBuf_;
};

extern "C" __global__ __aicore__ void masked_softmax_with_rel_pos_bias_fp16(
    GM_ADDR x, GM_ADDR attenMask, GM_ADDR relPosBias, GM_ADDR out, GM_ADDR tiling)
{
    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIC_1_1);
    AscendC::TPipe pipe;
    KernelMaskedSoftmaxWithRelPosBias<half> kernel;
    kernel.Init(x, attenMask, relPosBias, out, tiling, &pipe);
    kernel.Process();
}

extern "C" __global__ __aicore__ void masked_softmax_with_rel_pos_bias_fp32(
    GM_ADDR x, GM_ADDR attenMask, GM_ADDR relPosBias, GM_ADDR out, GM_ADDR tiling)
{
    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIC_1_1);
    AscendC::TPipe pipe;
    KernelMaskedSoftmaxWithRelPosBias<float> kernel;
    kernel.Init(x, attenMask, relPosBias, out, tiling, &pipe);
    kernel.Process();
}

extern "C" __global__ __aicore__ void masked_softmax_with_rel_pos_bias_bf16(
    GM_ADDR x, GM_ADDR attenMask, GM_ADDR relPosBias, GM_ADDR out, GM_ADDR tiling)
{
    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIC_1_1);
    AscendC::TPipe pipe;
    KernelMaskedSoftmaxWithRelPosBias<bfloat16_t> kernel;
    kernel.Init(x, attenMask, relPosBias, out, tiling, &pipe);
    kernel.Process();
}
