#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_masked_softmax_with_rel_pos_bias_fp16.h"
#include "aclrtlaunch_masked_softmax_with_rel_pos_bias_fp32.h"
#include "aclrtlaunch_masked_softmax_with_rel_pos_bias_bf16.h"

namespace ascend_kernel {

struct TilingData {
    int64_t totalRows;
    int64_t rowLength;
    int64_t hasAttenMask;
    float scaleValue;
    int64_t formerNum;
    int64_t formerLength;
    int64_t tailNum;
    int64_t tailLength;
    int64_t tileLength;
    int64_t blockRows;
};

at::Tensor masked_softmax_with_rel_pos_bias(
    const at::Tensor &x,
    const at::Tensor &attenMask,
    const at::Tensor &relPosBias,
    double scale_value,
    int64_t has_atten_mask)
{
    // Create output tensor
    auto output = at::empty_like(x);

    // Flatten all dims except last
    int64_t totalRows = 1;
    for (int64_t i = 0; i < x.dim() - 1; i++) {
        totalRows *= x.size(i);
    }
    int64_t rowLength = x.size(-1);

    // Get platform info
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());

    uint64_t ubSize;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    // Block-level tiling
    int64_t blockRows = 8;
    int64_t totalElements = totalRows * rowLength;
    int64_t dtypeSize = x.element_size();

    // UB-level tiling: calculate tileLength
    // Buffer coefficient: x + out + bias + mask + tmp_fp32*3 + max + sum + reduce_tmp
    // For fp16: input buffers (3-4) * tileLength * 2 + fp32 buffers * tileLength * 4
    int64_t bufferCoefficient = 48; // Conservative estimate
    int64_t tileLength = (static_cast<int64_t>(ubSize) / bufferCoefficient) / dtypeSize;
    tileLength = (tileLength / 32) * 32; // 32B align
    if (tileLength < rowLength) {
        tileLength = rowLength;
    }
    if (tileLength > totalElements) {
        tileLength = totalElements;
    }

    // Block-level: divide totalElements by tileLength
    int64_t tileNum = (totalElements + tileLength - 1) / tileLength;
    int64_t usedCoreNum = std::min(coreNum, tileNum);
    int64_t formerNum = (tileNum + usedCoreNum - 1) / usedCoreNum;
    int64_t formerLength = tileLength;
    int64_t tailNum = tileNum - formerNum * (usedCoreNum - 1);
    if (tailNum < 0) tailNum = 0;
    int64_t tailLength = totalElements - formerNum * formerLength * (usedCoreNum - 1);
    if (tailLength < 0) tailLength = 0;
    if (tailNum > 0 && tailLength == 0) {
        tailLength = tileLength;
    }

    // Prepare tiling data
    TilingData tiling;
    tiling.totalRows = totalRows;
    tiling.rowLength = rowLength;
    tiling.hasAttenMask = has_atten_mask;
    tiling.scaleValue = static_cast<float>(scale_value);
    tiling.formerNum = formerNum;
    tiling.formerLength = formerLength;
    tiling.tailNum = tailNum;
    tiling.tailLength = tailLength;
    tiling.tileLength = tileLength;
    tiling.blockRows = blockRows;

    // Create tiling tensor on device
    auto tilingTensor = at::empty({sizeof(TilingData) / sizeof(int64_t)}, at::TensorOptions().dtype(at::kLong).device(x.device()));
    auto tilingHost = at::empty({sizeof(TilingData) / sizeof(int64_t)}, at::TensorOptions().dtype(at::kLong));
    memcpy(tilingHost.data_ptr<int64_t>(), &tiling, sizeof(TilingData));
    tilingTensor.copy_(tilingHost);

    int64_t blockDim = usedCoreNum;

    // Handle optional attenMask - create empty tensor if not present
    at::Tensor attenMaskTensor;
    if (has_atten_mask == 1 && attenMask.defined() && attenMask.numel() > 0) {
        attenMaskTensor = attenMask;
    } else {
        attenMaskTensor = at::empty({0}, x.options());
    }

    // Launch kernel based on dtype
    if (x.dtype() == at::kHalf) {
        EXEC_KERNEL_CMD(masked_softmax_with_rel_pos_bias_fp16, blockDim,
            x, attenMaskTensor, relPosBias, output, tilingTensor);
    } else if (x.dtype() == at::kFloat) {
        EXEC_KERNEL_CMD(masked_softmax_with_rel_pos_bias_fp32, blockDim,
            x, attenMaskTensor, relPosBias, output, tilingTensor);
    } else if (x.dtype() == at::kBFloat16) {
        EXEC_KERNEL_CMD(masked_softmax_with_rel_pos_bias_bf16, blockDim,
            x, attenMaskTensor, relPosBias, output, tilingTensor);
    } else {
        TORCH_CHECK(false, "Unsupported dtype for masked_softmax_with_rel_pos_bias");
    }

    return output;
}

} // namespace ascend_kernel
