51	// Strategy-agnostic helper functions
52	// =========================================================================
53	
54	__aicore__ inline int32_t BlockCountHelper(int32_t M, int32_t blockM)
55	{
56	    if (blockM == 0) { return 0; }
57	    return (M + blockM - 1) / blockM;
58	}
59	
60	template <typename T>
61	__aicore__ inline AscendC::RoundMode OutputRoundModeHelper()
62	{
63	    if constexpr (std::is_same_v<T, bfloat16_t>) {
64	        return AscendC::RoundMode::CAST_ROUND;
65	    }
66	    return AscendC::RoundMode::CAST_NONE;
67	}
68	
69	template <typename T>
70	__aicore__ inline void PrepareInputTensorHelper(
71	    AscendC::LocalTensor<float> &dst,
72	    AscendC::LocalTensor<T> &src,
73	    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
74	    int32_t count)
75	{
76	    if constexpr (std::is_same_v<T, float>) {
77	        dst = src.template ReinterpretCast<float>();
78	    } else {
79	        dst = castBuf.Get<float>();
80	        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
81	        AscendC::PipeBarrier<PIPE_V>();
82	    }
83	}
