191	// =========================================================================
192	// Strategy 1: merge_n — preferred when N <= 1024
193	// =========================================================================
194	
195	template <typename dataType>
196	class RmsNormMergeNKernel {
197	public:
198	    __aicore__ inline void Init(
199	        GM_ADDR x, GM_ADDR gamma, GM_ADDR y, GM_ADDR invRms,
200	        int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
201	        int32_t tasksPerCore, int32_t rowFactor, float eps, float invN)
202	    {
203	        this->M = M;
204	        this->N = N;
205	        this->blockM = blockM;
206	        this->usedCoreNum = usedCoreNum;
207	        this->tasksPerCore = tasksPerCore;
208	        this->rowFactor = rowFactor;
209	        this->eps = eps;
210	        this->invN = invN;
211	
212	        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x), static_cast<uint64_t>(M) * N);
213	        gammaGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(gamma), N);
214	        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y), static_cast<uint64_t>(M) * N);
215	        invRmsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(invRms), M);
216	
217	        if ASCEND_IS_AIV { InitAivBuffers(); }
218	    }
219	
220	    __aicore__ inline void InitAivBuffers()
221	    {
222	        subBlockRows_ = blockM / AscendC::GetSubBlockNum();
223	        rowLoops_ = subBlockRows_ / rowFactor;
224	        pipe.InitBuffer(gammaBuf_, N * sizeof(dataType));
225	        pipe.InitBuffer(xInQueue_, BUFFER_NUM, kMergeRowFactor * N * sizeof(dataType));
226	        pipe.InitBuffer(yOutQueue_, BUFFER_NUM, kMergeRowFactor * N * sizeof(dataType));
227	        pipe.InitBuffer(invRmsOutQueue_, BUFFER_NUM, kMergeRowFactor * sizeof(dataType));
228	        pipe.InitBuffer(scaleBuf_, kMergeRowFactor * N * sizeof(float));
229	        pipe.InitBuffer(gammaTileBuf_, kMergeRowFactor * N * sizeof(float));
230	        pipe.InitBuffer(gammaBroadcastTmpBuf_, 2 * kMergeRowFactor * N * sizeof(uint8_t));
231	        pipe.InitBuffer(scaleBroadcastTmpBuf_, 2 * kMergeRowFactor * N * sizeof(uint8_t));
232	        pipe.InitBuffer(reduceBuf_, 2 * kMergeRowFactor * N * sizeof(uint8_t));
233	        pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
234	        pipe.InitBuffer(invRmsBuf_, kMergeRowFactor * sizeof(float));
235	        if constexpr (!std::is_same_v<dataType, float>) {
236	            pipe.InitBuffer(xCastBuf_, kMergeRowFactor * N * sizeof(float));
237	            pipe.InitBuffer(gammaCastBuf_, N * sizeof(float));
238	            pipe.InitBuffer(yCastBuf_, kMergeRowFactor * N * sizeof(float));
239	        }
240	
241	        const uint32_t gammaSrcShape[2] = {1U, static_cast<uint32_t>(N)};
242	        const uint32_t gammaDstShape[2] = {
243	            static_cast<uint32_t>(kMergeRowFactor),
244	            static_cast<uint32_t>(N),
245	        };
246	
247	        gammaInLocal_ = gammaBuf_.Get<dataType>();
248	        LoadGmToUb(gammaInLocal_, gammaGM_, static_cast<uint32_t>(N));
249	        AscendC::PipeBarrier<PIPE_MTE2>();
250	        AscendC::PipeBarrier<PIPE_ALL>();
251	        PrepareInputTensor(gammaLocal_, gammaInLocal_, gammaCastBuf_, N);
252	
253	        gammaTileLocal_ = gammaTileBuf_.Get<float>();
254	        gammaBroadcastTmpLocal_ = gammaBroadcastTmpBuf_.Get<uint8_t>();
255	        AscendC::PipeBarrier<PIPE_ALL>();
256	        AscendC::Broadcast<float, 2, 0>(
257	            gammaTileLocal_,
258	            gammaLocal_,
259	            gammaDstShape,
260	            gammaSrcShape,
261	            gammaBroadcastTmpLocal_);
262	        AscendC::PipeBarrier<PIPE_V>();
263	    }
264	
265	    __aicore__ inline void Process()
266	    {
267	        if ASCEND_IS_AIV {
268	            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
269	            const int subBlockIdx = AscendC::GetSubBlockIdx();
270	
271	            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
272	                const int bx = coreIdx * tasksPerCore + localIdx;
273	                if (bx >= BlockCountHelper(M, blockM)) {
274	                    continue;
275	                }
276	
277	                for (int r = 0; r < rowLoops_; ++r) {
278	                    const int rowBase = bx * blockM + subBlockIdx * subBlockRows_ + r * rowFactor;
279	                    const int validRows = M - rowBase;
280	                    if (validRows > 0) {
281	                        ProcessRows(rowBase, validRows >= kMergeRowFactor ? kMergeRowFactor : validRows);
282	                    }
283	                }
284	            }
285	        }
286	    }
287	
288	private:
289	    static constexpr int kMergeRowFactor = 8;
290	
291	    __aicore__ inline void CopyInX(int32_t rowBase, int32_t count)
292	    {
293	        xInLocal_ = xInQueue_.AllocTensor<dataType>();
294	        LoadGmToUb(xInLocal_, xGM_[static_cast<uint64_t>(rowBase) * N], static_cast<uint32_t>(count));
295	        xInQueue_.EnQue(xInLocal_);
296	    }
297	
298	    __aicore__ inline void CopyOutY(int32_t rowBase, int32_t count)
299	    {
300	        yOutLocal_ = yOutQueue_.DeQue<dataType>();
301	        StoreUbToGm(yGM_[static_cast<uint64_t>(rowBase) * N], yOutLocal_, static_cast<uint32_t>(count));
302	        yOutQueue_.FreeTensor(yOutLocal_);
303	    }
304	
305	    __aicore__ inline void CopyOutInvRms(int32_t rowBase, int32_t count)
306	    {
307	        invRmsOutLocal_ = invRmsOutQueue_.DeQue<dataType>();
308	        StoreUbToGm(invRmsGM_[rowBase], invRmsOutLocal_, static_cast<uint32_t>(count));
309	        invRmsOutQueue_.FreeTensor(invRmsOutLocal_);
310	    }
311	
312	    __aicore__ inline void ComputeSingleRow()
313	    {
314	        const uint32_t reduceShape[2] = {1U, static_cast<uint32_t>(N)};
315	        const uint32_t scaleSrcShape[2] = {1U, 1U};
316	        const uint32_t scaleDstShape[2] = {1U, static_cast<uint32_t>(N)};
317	
318	        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
319	        scaleLocal_ = scaleBuf_.Get<float>();
320	        reduceTmpLocal_ = reduceBuf_.Get<uint8_t>();
321	        sumLocal_ = sumBuf_.Get<float>();
322	        invRmsOutLocal_ = invRmsOutQueue_.AllocTensor<dataType>();
323	        PrepareInvRmsTensorHelper<dataType>(invRmsLocal_, invRmsOutLocal_, invRmsBuf_);
324	        scaleBroadcastTmpLocal_ = scaleBroadcastTmpBuf_.Get<uint8_t>();
325	
326	        xInLocal_ = xInQueue_.DeQue<dataType>();
327	        PrepareInputTensorHelper<dataType>(xLocal_, xInLocal_, xCastBuf_, N);
328	        PrepareOutputTensorHelper<dataType>(yLocal_, yOutLocal_, yCastBuf_);
329	
330	        AscendC::Mul(yLocal_, xLocal_, xLocal_, N);
331	        AscendC::ReduceSum<float, AscendC::Pattern::Reduce::AR, false>(
332	            sumLocal_, yLocal_, reduceTmpLocal_, reduceShape, true);
333	        AscendC::Muls(sumLocal_, sumLocal_, invN, 1);
334	        AscendC::Adds(sumLocal_, sumLocal_, eps, 1);
335	        AscendC::Rsqrt(invRmsLocal_, sumLocal_, 1);
336	        FinalizeOutputTensorHelper<dataType>(invRmsOutLocal_, invRmsLocal_, 1);
337	        AscendC::PipeBarrier<PIPE_V>();
338	        AscendC::Broadcast<float, 2, 1>(
339	            scaleLocal_, invRmsLocal_, scaleDstShape, scaleSrcShape, scaleBroadcastTmpLocal_);
340	
341	        AscendC::Mul(yLocal_, xLocal_, scaleLocal_, N);
342	        AscendC::Mul(yLocal_, yLocal_, gammaLocal_, N);
343	        FinalizeOutputTensorHelper<dataType>(yOutLocal_, yLocal_, N);
344	
345	        xInQueue_.FreeTensor(xInLocal_);
346	        yOutQueue_.EnQue(yOutLocal_);
347	        invRmsOutQueue_.EnQue(invRmsOutLocal_);
348	    }
349	
350	    __aicore__ inline void ComputeRows(int32_t tileSize)
351	    {
352	        const uint32_t reduceShape[2] = {
353	            static_cast<uint32_t>(kMergeRowFactor),
354	            static_cast<uint32_t>(N),
355	        };
356	        const uint32_t scaleSrcShape[2] = {
357	            static_cast<uint32_t>(kMergeRowFactor),
358	            1U,
359	        };
360	        const uint32_t scaleDstShape[2] = {
361	            static_cast<uint32_t>(kMergeRowFactor),
362	            static_cast<uint32_t>(N),
363	        };
364	
365	        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
366	        scaleLocal_ = scaleBuf_.Get<float>();
367	        reduceTmpLocal_ = reduceBuf_.Get<uint8_t>();
368	        sumLocal_ = sumBuf_.Get<float>();
369	        invRmsOutLocal_ = invRmsOutQueue_.AllocTensor<dataType>();
370	        PrepareInvRmsTensorHelper<dataType>(invRmsLocal_, invRmsOutLocal_, invRmsBuf_);
371	        scaleBroadcastTmpLocal_ = scaleBroadcastTmpBuf_.Get<uint8_t>();
372	
373	        xInLocal_ = xInQueue_.DeQue<dataType>();
374	        PrepareInputTensorHelper<dataType>(xLocal_, xInLocal_, xCastBuf_, tileSize);
375	        PrepareOutputTensorHelper<dataType>(yLocal_, yOutLocal_, yCastBuf_);
376	
377	        AscendC::Mul(yLocal_, xLocal_, xLocal_, tileSize);
378	        AscendC::ReduceSum<float, AscendC::Pattern::Reduce::AR, false>(
379	            sumLocal_, yLocal_, reduceTmpLocal_, reduceShape, true);
380	        AscendC::Muls(sumLocal_, sumLocal_, invN, kMergeRowFactor);
381	        AscendC::Adds(sumLocal_, sumLocal_, eps, kMergeRowFactor);
382	        AscendC::Rsqrt(invRmsLocal_, sumLocal_, kMergeRowFactor);
383	        FinalizeOutputTensorHelper<dataType>(invRmsOutLocal_, invRmsLocal_, kMergeRowFactor);
384	        AscendC::PipeBarrier<PIPE_V>();
385	        AscendC::Broadcast<float, 2, 1>(
386	            scaleLocal_, invRmsLocal_, scaleDstShape, scaleSrcShape, scaleBroadcastTmpLocal_);
387	
388	        AscendC::Mul(yLocal_, xLocal_, scaleLocal_, tileSize);
389	        AscendC::Mul(yLocal_, yLocal_, gammaTileLocal_, tileSize);
390	        FinalizeOutputTensorHelper<dataType>(yOutLocal_, yLocal_, tileSize);
391	
392	        xInQueue_.FreeTensor(xInLocal_);
393	        yOutQueue_.EnQue(yOutLocal_);
394	        invRmsOutQueue_.EnQue(invRmsOutLocal_);
395	    }
396	
397	    __aicore__ inline void ProcessSingleRow(int rowIdx)
398	    {
399	        CopyInX(rowIdx, N);
400	        ComputeSingleRow();
401	        CopyOutInvRms(rowIdx, 1);
402	        CopyOutY(rowIdx, N);
403	    }
404	
405	    __aicore__ inline void ProcessRows(int rowBase, int validRows)
406	    {
407	        if (validRows < kMergeRowFactor) {
408	            for (int r = 0; r < validRows; ++r) {
409	                ProcessSingleRow(rowBase + r);
410	            }
411	            return;
412	        }
413	
414	        const int tileSize = kMergeRowFactor * N;
415	        CopyInX(rowBase, tileSize);
416	        ComputeRows(tileSize);
417	        CopyOutInvRms(rowBase, validRows);
418	        CopyOutY(rowBase, tileSize);
419	    }
420	
421	private:
422	    int32_t M = 0;
423	    int32_t N = 0;
424	    int32_t blockM = 0;
425	    int32_t usedCoreNum = 0;
426	    int32_t tasksPerCore = 0;
427	    int32_t rowFactor = 0;
428	    float eps = 0.0f;
429	    float invN = 0.0f;
430	    int subBlockRows_ = 0;
431	    int rowLoops_ = 0;
432	
433	    AscendC::TPipe pipe;
434	    AscendC::GlobalTensor<dataType> xGM_;
435	    AscendC::GlobalTensor<dataType> gammaGM_;
436	    AscendC::GlobalTensor<dataType> yGM_;
437	    AscendC::GlobalTensor<dataType> invRmsGM_;
438	
439	    AscendC::TBuf<AscendC::TPosition::VECCALC> gammaBuf_;
440	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
441	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
442	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> invRmsOutQueue_;
443	    AscendC::TBuf<AscendC::TPosition::VECCALC> scaleBuf_;
444	    AscendC::TBuf<AscendC::TPosition::VECCALC> gammaTileBuf_;
445	    AscendC::TBuf<AscendC::TPosition::VECCALC> gammaBroadcastTmpBuf_;
446	    AscendC::TBuf<AscendC::TPosition::VECCALC> scaleBroadcastTmpBuf_;
447	    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_;
448	    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
449	    AscendC::TBuf<AscendC::TPosition::VECCALC> invRmsBuf_;
450	    AscendC::TBuf<AscendC::TPosition::VECCALC> xCastBuf_;
451	    AscendC::TBuf<AscendC::TPosition::VECCALC> gammaCastBuf_;
452	    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf_;
453	
454	    AscendC::LocalTensor<dataType> gammaInLocal_;
455	    AscendC::LocalTensor<dataType> xInLocal_;
456	    AscendC::LocalTensor<dataType> yOutLocal_;
457	    AscendC::LocalTensor<dataType> invRmsOutLocal_;
458	    AscendC::LocalTensor<float> gammaLocal_;
459	    AscendC::LocalTensor<float> xLocal_;
