#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;

// ---------------------------------------------------------------------------
// Inline helpers
// ---------------------------------------------------------------------------

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst,
    AscendC::GlobalTensor<T> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

__aicore__ inline int32_t BlockCountHelper(int32_t M, int32_t blockM)
{
    if (blockM == 0) { return 0; }
    return (M + blockM - 1) / blockM;
}

template <typename T>
__aicore__ inline AscendC::RoundMode OutputRoundModeHelper()
{
    if constexpr (std::is_same_v<T, bfloat16_t>) {
        return AscendC::RoundMode::CAST_ROUND;
    }
    return AscendC::RoundMode::CAST_NONE;
}

// =========================================================================
// MaskedSoftmaxWithRelPosBias kernel
// Computes: softmax(scale * x + atten_mask + relative_pos_bias) along last dim
// =========================================================================

template <typename dataType>
class MaskedSoftmaxKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR attenMask, GM_ADDR relPosBias, GM_ADDR out,
        int32_t totalRows, int32_t rowLength, int32_t hasAttenMask,
        float scaleValue, int32_t blockRows, int32_t usedCoreNum,
        int32_t tasksPerCore)
    {
        this->totalRows = totalRows;
        this->rowLength = rowLength;
        this->hasAttenMask = hasAttenMask;
        this->scaleValue = scaleValue;
        this->blockRows = blockRows;
        this->usedCoreNum = usedCoreNum;
        this->tasksPerCore = tasksPerCore;

        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x),
            static_cast<uint64_t>(totalRows) * rowLength);
        attenMaskGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(attenMask),
            static_cast<uint64_t>(totalRows) * rowLength);
        relPosBiasGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(relPosBias),
            static_cast<uint64_t>(totalRows) * rowLength);
        outGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(out),
            static_cast<uint64_t>(totalRows) * rowLength);

        if ASCEND_IS_AIV { InitAivBuffers(); }
    }

    __aicore__ inline void InitAivBuffers()
    {
        subBlockRows_ = blockRows / AscendC::GetSubBlockNum();
        if (subBlockRows_ < 1) subBlockRows_ = 1;

        uint32_t rowBytes = static_cast<uint32_t>(rowLength) * sizeof(dataType);
        uint32_t rowFloatBytes = static_cast<uint32_t>(rowLength) * sizeof(float);

        pipe.InitBuffer(xInQueue_, BUFFER_NUM, rowBytes);
        pipe.InitBuffer(biasInQueue_, BUFFER_NUM, rowBytes);
        if (hasAttenMask == 1) {
            pipe.InitBuffer(maskInQueue_, BUFFER_NUM, rowBytes);
        }
        pipe.InitBuffer(outQueue_, BUFFER_NUM, rowBytes);

        // FP32 computation buffers
        pipe.InitBuffer(tmpFp32Buf_, rowFloatBytes);
        pipe.InitBuffer(maxBuf_, sizeof(float));
        pipe.InitBuffer(sumBuf_, sizeof(float));
        pipe.InitBuffer(reduceBuf_, 2 * rowLength * sizeof(uint8_t));
        pipe.InitBuffer(broadcastBuf_, rowFloatBytes);

        if constexpr (!std::is_same_v<dataType, float>) {
            pipe.InitBuffer(castBuf_, rowFloatBytes);
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            const int subBlockIdx = AscendC::GetSubBlockIdx();

            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
                const int bx = coreIdx * tasksPerCore + localIdx;
                if (bx >= BlockCountHelper(totalRows, blockRows)) {
                    continue;
                }

                for (int row = 0; row < subBlockRows_; ++row) {
                    const int rowIdx = bx * blockRows + subBlockIdx * subBlockRows_ + row;
                    if (rowIdx < totalRows) {
                        ProcessRow(rowIdx);
                    }
                }
            }
        }
    }

private:
    __aicore__ inline void CopyInRow(int32_t rowIdx)
    {
        uint64_t offset = static_cast<uint64_t>(rowIdx) * rowLength;

        xInLocal_ = xInQueue_.AllocTensor<dataType>();
        LoadGmToUb(xInLocal_, xGM_[offset], static_cast<uint32_t>(rowLength));
        xInQueue_.EnQue(xInLocal_);

        biasInLocal_ = biasInQueue_.AllocTensor<dataType>();
        LoadGmToUb(biasInLocal_, relPosBiasGM_[offset], static_cast<uint32_t>(rowLength));
        biasInQueue_.EnQue(biasInLocal_);

        if (hasAttenMask == 1) {
            maskInLocal_ = maskInQueue_.AllocTensor<dataType>();
            LoadGmToUb(maskInLocal_, attenMaskGM_[offset], static_cast<uint32_t>(rowLength));
            maskInQueue_.EnQue(maskInLocal_);
        }
    }

    __aicore__ inline void CopyOutRow(int32_t rowIdx)
    {
        uint64_t offset = static_cast<uint64_t>(rowIdx) * rowLength;
        outLocal_ = outQueue_.DeQue<dataType>();
        StoreUbToGm(outGM_[offset], outLocal_, static_cast<uint32_t>(rowLength));
        outQueue_.FreeTensor(outLocal_);
    }

    __aicore__ inline void ComputeRow()
    {
        outLocal_ = outQueue_.AllocTensor<dataType>();
        tmpFp32Local_ = tmpFp32Buf_.Get<float>();
        maxLocal_ = maxBuf_.Get<float>();
        sumLocal_ = sumBuf_.Get<float>();
        reduceLocal_ = reduceBuf_.Get<uint8_t>();
        broadcastLocal_ = broadcastBuf_.Get<float>();

        // Load x and cast to FP32
        xInLocal_ = xInQueue_.DeQue<dataType>();
        if constexpr (std::is_same_v<dataType, float>) {
            AscendC::DataCopy(tmpFp32Local_, xInLocal_.template ReinterpretCast<float>(), rowLength);
        } else {
            AscendC::Cast(tmpFp32Local_, xInLocal_, AscendC::RoundMode::CAST_NONE, rowLength);
        }
        AscendC::PipeBarrier<PIPE_V>();

        // Multiply by scale
        AscendC::Muls(tmpFp32Local_, tmpFp32Local_, scaleValue, rowLength);

        // Load bias and add
        biasInLocal_ = biasInQueue_.DeQue<dataType>();
        if constexpr (std::is_same_v<dataType, float>) {
            AscendC::Add(tmpFp32Local_, tmpFp32Local_,
                biasInLocal_.template ReinterpretCast<float>(), rowLength);
        } else {
            AscendC::LocalTensor<float> biasFp32 = castBuf_.Get<float>();
            AscendC::Cast(biasFp32, biasInLocal_, AscendC::RoundMode::CAST_NONE, rowLength);
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::Add(tmpFp32Local_, tmpFp32Local_, biasFp32, rowLength);
        }

        // Add atten_mask if present
        if (hasAttenMask == 1) {
            maskInLocal_ = maskInQueue_.DeQue<dataType>();
            if constexpr (std::is_same_v<dataType, float>) {
                AscendC::Add(tmpFp32Local_, tmpFp32Local_,
                    maskInLocal_.template ReinterpretCast<float>(), rowLength);
            } else {
                AscendC::LocalTensor<float> maskFp32 = castBuf_.Get<float>();
                AscendC::Cast(maskFp32, maskInLocal_, AscendC::RoundMode::CAST_NONE, rowLength);
                AscendC::PipeBarrier<PIPE_V>();
                AscendC::Add(tmpFp32Local_, tmpFp32Local_, maskFp32, rowLength);
            }
            maskInQueue_.FreeTensor(maskInLocal_);
        }

        // Softmax step 1: find max
        AscendC::ReduceMax<float>(maxLocal_, tmpFp32Local_, reduceLocal_, rowLength);
        AscendC::PipeBarrier<PIPE_ALL>();
        float rowMax = maxLocal_.GetValue(0);
        AscendC::PipeBarrier<PIPE_ALL>();

        // Softmax step 2: subtract max (broadcast)
        AscendC::Duplicate(broadcastLocal_, rowMax, rowLength);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Sub(tmpFp32Local_, tmpFp32Local_, broadcastLocal_, rowLength);

        // Softmax step 3: exp
        AscendC::Exp(tmpFp32Local_, tmpFp32Local_, rowLength);
        AscendC::PipeBarrier<PIPE_V>();

        // Softmax step 4: sum
        AscendC::ReduceSum<float>(sumLocal_, tmpFp32Local_, reduceLocal_, rowLength);
        AscendC::PipeBarrier<PIPE_ALL>();
        float rowSum = sumLocal_.GetValue(0);
        AscendC::PipeBarrier<PIPE_ALL>();

        // Softmax step 5: divide by sum (broadcast)
        AscendC::Duplicate(broadcastLocal_, rowSum, rowLength);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Div(tmpFp32Local_, tmpFp32Local_, broadcastLocal_, rowLength);

        // Cast back to output dtype
        if constexpr (std::is_same_v<dataType, float>) {
            AscendC::DataCopy(outLocal_.template ReinterpretCast<float>(), tmpFp32Local_, rowLength);
        } else {
            AscendC::Cast(outLocal_, tmpFp32Local_, OutputRoundModeHelper<dataType>(), rowLength);
        }
        AscendC::PipeBarrier<PIPE_V>();

        xInQueue_.FreeTensor(xInLocal_);
        biasInQueue_.FreeTensor(biasInLocal_);
        outQueue_.EnQue(outLocal_);
    }

    __aicore__ inline void ProcessRow(int rowIdx)
    {
        CopyInRow(rowIdx);
        ComputeRow();
        CopyOutRow(rowIdx);
    }

private:
    int32_t totalRows = 0;
    int32_t rowLength = 0;
    int32_t hasAttenMask = 0;
    float scaleValue = 1.0f;
    int32_t blockRows = 0;
    int32_t usedCoreNum = 0;
    int32_t tasksPerCore = 0;
    int32_t subBlockRows_ = 0;

    AscendC::TPipe pipe;
    AscendC::GlobalTensor<dataType> xGM_;
    AscendC::GlobalTensor<dataType> attenMaskGM_;
    AscendC::GlobalTensor<dataType> relPosBiasGM_;
    AscendC::GlobalTensor<dataType> outGM_;

    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> biasInQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> maskInQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueue_;

    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpFp32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> maxBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> broadcastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> castBuf_;

    AscendC::LocalTensor<dataType> xInLocal_;
    AscendC::LocalTensor<dataType> biasInLocal_;
    AscendC::LocalTensor<dataType> maskInLocal_;
    AscendC::LocalTensor<dataType> outLocal_;
    AscendC::LocalTensor<float> tmpFp32Local_;
    AscendC::LocalTensor<float> maxLocal_;
    AscendC::LocalTensor<float> sumLocal_;
    AscendC::LocalTensor<uint8_t> reduceLocal_;
    AscendC::LocalTensor<float> broadcastLocal_;
};

