extern "C" __global__ __aicore__ void masked_softmax_with_rel_pos_bias(
    GM_ADDR x, GM_ADDR attenMask, GM_ADDR relPosBias, GM_ADDR out,
    int32_t totalRows, int32_t rowLength, int32_t hasAttenMask,
    float scaleValue, int32_t blockRows, int32_t usedCoreNum,
    int32_t tasksPerCore, int64_t dtypeFlag)
{
    if (dtypeFlag == 0) {
        MaskedSoftmaxKernel<float> kernel;
        kernel.Init(x, attenMask, relPosBias, out,
            totalRows, rowLength, hasAttenMask, scaleValue,
            blockRows, usedCoreNum, tasksPerCore);
        kernel.Process();
    } else if (dtypeFlag == 1) {
        MaskedSoftmaxKernel<half> kernel;
        kernel.Init(x, attenMask, relPosBias, out,
            totalRows, rowLength, hasAttenMask, scaleValue,
            blockRows, usedCoreNum, tasksPerCore);
        kernel.Process();
    } else {
        MaskedSoftmaxKernel<bfloat16_t> kernel;
        kernel.Init(x, attenMask, relPosBias, out,
            totalRows, rowLength, hasAttenMask, scaleValue,
            blockRows, usedCoreNum, tasksPerCore);
        kernel.Process();
    }
}
