#include <algorithm>
#include <cstdint>

#include <torch/extension.h>
#include <torch/library.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_masked_softmax_with_rel_pos_bias.h"

// ---------------------------------------------------------------------------
// Tiling constants
// ---------------------------------------------------------------------------

constexpr int32_t DEFAULT_BLOCK_ROWS = 8;
constexpr int32_t DEFAULT_NUM_PHYSICAL_CORES = 20;

// ---------------------------------------------------------------------------
// Host function
// ---------------------------------------------------------------------------

namespace ascend_kernel {

at::Tensor masked_softmax_with_rel_pos_bias(
    const at::Tensor &x,
    const at::Tensor &attenMask,
    const at::Tensor &relPosBias,
    double scale_value,
    int64_t has_atten_mask)
{
    TORCH_CHECK(
        x.scalar_type() == at::kFloat || x.scalar_type() == at::kHalf ||
            x.scalar_type() == at::kBFloat16,
        "x must be float16, float32, or bfloat16");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");

    // Flatten all dims except last into totalRows
    int32_t totalRows = 1;
    for (int64_t i = 0; i < x.dim() - 1; i++) {
        totalRows *= static_cast<int32_t>(x.size(i));
    }
    int32_t rowLength = static_cast<int32_t>(x.size(-1));

    at::Tensor output = at::empty_like(x);

    // Get platform info
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int32_t coreNum = static_cast<int32_t>(ascendc_platform->GetCoreNumAiv());

    // Block-level tiling
    int32_t rowNum = BlockCountHelper(totalRows, DEFAULT_BLOCK_ROWS);
    int32_t usedCoreNum = std::min<int32_t>(DEFAULT_NUM_PHYSICAL_CORES, std::max<int32_t>(1, rowNum));
    int32_t tasksPerCore = (rowNum + usedCoreNum - 1) / usedCoreNum;

    // dtype flag: 0=fp32, 1=fp16, 2=bf16
    int64_t dtypeFlag = 0;
    if (x.scalar_type() == at::kHalf) {
        dtypeFlag = 1;
    } else if (x.scalar_type() == at::kBFloat16) {
        dtypeFlag = 2;
    }

    // All params as left values (required by EXEC_KERNEL_CMD)
    int32_t blockRows = DEFAULT_BLOCK_ROWS;
    float scaleValue = static_cast<float>(scale_value);
    int32_t hasAttenMask = static_cast<int32_t>(has_atten_mask);
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    // Handle optional attenMask - create empty tensor if not present
    at::Tensor attenMaskTensor;
    if (hasAttenMask == 1 && attenMask.defined() && attenMask.numel() > 0) {
        attenMaskTensor = attenMask;
    } else {
        attenMaskTensor = at::empty({0}, x.options());
    }

    EXEC_KERNEL_CMD(masked_softmax_with_rel_pos_bias, blockDim,
                    x, attenMaskTensor, relPosBias, output,
                    totalRows, rowLength, hasAttenMask,
                    scaleValue, blockRows, usedCoreNum, tasksPerCore,
                    dtypeFlag);

    return output;
}

}  // namespace ascend_kernel
