60	template <typename dataType>
61	class MaskedSoftmaxKernel {
62	public:
63	    __aicore__ inline void Init(
64	        GM_ADDR x, GM_ADDR attenMask, GM_ADDR relPosBias, GM_ADDR out,
65	        int32_t totalRows, int32_t rowLength, int32_t hasAttenMask,
66	        float scaleValue, int32_t blockRows, int32_t usedCoreNum,
67	        int32_t tasksPerCore)
68	    {
69	        this->totalRows = totalRows;
70	        this->rowLength = rowLength;
71	        this->hasAttenMask = hasAttenMask;
72	        this->scaleValue = scaleValue;
73	        this->blockRows = blockRows;
74	        this->usedCoreNum = usedCoreNum;
75	        this->tasksPerCore = tasksPerCore;
76	
77	        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x),
78	            static_cast<uint64_t>(totalRows) * rowLength);
79	        attenMaskGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(attenMask),
80	            static_cast<uint64_t>(totalRows) * rowLength);
81	        relPosBiasGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(relPosBias),
82	            static_cast<uint64_t>(totalRows) * rowLength);
83	        outGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(out),
84	            static_cast<uint64_t>(totalRows) * rowLength);
85	
86	        if ASCEND_IS_AIV { InitAivBuffers(); }
87	    }
88	
89	    __aicore__ inline void InitAivBuffers()
90	    {
91	        subBlockRows_ = blockRows / AscendC::GetSubBlockNum();
92	        if (subBlockRows_ < 1) subBlockRows_ = 1;
93	
94	        uint32_t rowBytes = static_cast<uint32_t>(rowLength) * sizeof(dataType);
95	        uint32_t rowFloatBytes = static_cast<uint32_t>(rowLength) * sizeof(float);
96	
97	        pipe.InitBuffer(xInQueue_, BUFFER_NUM, rowBytes);
98	        pipe.InitBuffer(biasInQueue_, BUFFER_NUM, rowBytes);
99	        if (hasAttenMask == 1) {
100	            pipe.InitBuffer(maskInQueue_, BUFFER_NUM, rowBytes);
101	        }
102	        pipe.InitBuffer(outQueue_, BUFFER_NUM, rowBytes);
103	
104	        // FP32 computation buffers
105	        pipe.InitBuffer(tmpFp32Buf_, rowFloatBytes);
106	        pipe.InitBuffer(maxBuf_, sizeof(float));
107	        pipe.InitBuffer(sumBuf_, sizeof(float));
108	        pipe.InitBuffer(reduceBuf_, 2 * rowLength * sizeof(uint8_t));
109	        pipe.InitBuffer(broadcastBuf_, rowFloatBytes);
110	
111	        if constexpr (!std::is_same_v<dataType, float>) {
112	            pipe.InitBuffer(castBuf_, rowFloatBytes);
113	        }
114	    }
115	
116	    __aicore__ inline void Process()
117	    {
118	        if ASCEND_IS_AIV {
119	            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
120	            const int subBlockIdx = AscendC::GetSubBlockIdx();
121	
122	            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
123	                const int bx = coreIdx * tasksPerCore + localIdx;
124	                if (bx >= BlockCountHelper(totalRows, blockRows)) {
125	                    continue;
126	                }
127	
128	                for (int row = 0; row < subBlockRows_; ++row) {
129	                    const int rowIdx = bx * blockRows + subBlockIdx * subBlockRows_ + row;
130	                    if (rowIdx < totalRows) {
131	                        ProcessRow(rowIdx);
132	                    }
133	                }
134	            }
135	        }
136	    }
137	
138	private:
139	    __aicore__ inline void CopyInRow(int32_t rowIdx)
140	    {
141	        uint64_t offset = static_cast<uint64_t>(rowIdx) * rowLength;
142	
143	        xInLocal_ = xInQueue_.AllocTensor<dataType>();
144	        LoadGmToUb(xInLocal_, xGM_[offset], static_cast<uint32_t>(rowLength));
145	        xInQueue_.EnQue(xInLocal_);
146	
147	        biasInLocal_ = biasInQueue_.AllocTensor<dataType>();
148	        LoadGmToUb(biasInLocal_, relPosBiasGM_[offset], static_cast<uint32_t>(rowLength));
149	        biasInQueue_.EnQue(biasInLocal_);
150	
151	        if (hasAttenMask == 1) {
152	            maskInLocal_ = maskInQueue_.AllocTensor<dataType>();
153	            LoadGmToUb(maskInLocal_, attenMaskGM_[offset], static_cast<uint32_t>(rowLength));
154	            maskInQueue_.EnQue(maskInLocal_);
155	        }
156	    }
157	
158	    __aicore__ inline void CopyOutRow(int32_t rowIdx)
159	    {
160	        uint64_t offset = static_cast<uint64_t>(rowIdx) * rowLength;
161	        outLocal_ = outQueue_.DeQue<dataType>();
162	        StoreUbToGm(outGM_[offset], outLocal_, static_cast<uint32_t>(rowLength));
163	        outQueue_.FreeTensor(outLocal_);
164	    }
165	
166	    __aicore__ inline void ComputeRow()
167	    {
168	        outLocal_ = outQueue_.AllocTensor<dataType>();
169	        tmpFp32Local_ = tmpFp32Buf_.Get<float>();
170	        maxLocal_ = maxBuf_.Get<float>();
171	        sumLocal_ = sumBuf_.Get<float>();
172	        reduceLocal_ = reduceBuf_.Get<uint8_t>();
173	        broadcastLocal_ = broadcastBuf_.Get<float>();
174	
175	        // Load x and cast to FP32
176	        xInLocal_ = xInQueue_.DeQue<dataType>();
177	        if constexpr (std::is_same_v<dataType, float>) {
178	            AscendC::DataCopy(tmpFp32Local_, xInLocal_.template ReinterpretCast<float>(), rowLength);
179	        } else {
180	            AscendC::Cast(tmpFp32Local_, xInLocal_, AscendC::RoundMode::CAST_NONE, rowLength);
181	        }
182	        AscendC::PipeBarrier<PIPE_V>();
183	
184	        // Multiply by scale
185	        AscendC::Muls(tmpFp32Local_, tmpFp32Local_, scaleValue, rowLength);
186	
187	        // Load bias and add
188	        biasInLocal_ = biasInQueue_.DeQue<dataType>();
189	        if constexpr (std::is_same_v<dataType, float>) {
190	            AscendC::Add(tmpFp32Local_, tmpFp32Local_,
191	                biasInLocal_.template ReinterpretCast<float>(), rowLength);
192	        } else {
193	            AscendC::LocalTensor<float> biasFp32 = castBuf_.Get<float>();
194	            AscendC::Cast(biasFp32, biasInLocal_, AscendC::RoundMode::CAST_NONE, rowLength);
195	            AscendC::PipeBarrier<PIPE_V>();
196	            AscendC::Add(tmpFp32Local_, tmpFp32Local_, biasFp32, rowLength);
197	        }
198	
199	        // Add atten_mask if present
200	        if (hasAttenMask == 1) {
201	            maskInLocal_ = maskInQueue_.DeQue<dataType>();
202	            if constexpr (std::is_same_v<dataType, float>) {
203	                AscendC::Add(tmpFp32Local_, tmpFp32Local_,
204	                    maskInLocal_.template ReinterpretCast<float>(), rowLength);
205	            } else {
206	                AscendC::LocalTensor<float> maskFp32 = castBuf_.Get<float>();
207	                AscendC::Cast(maskFp32, maskInLocal_, AscendC::RoundMode::CAST_NONE, rowLength);
208	                AscendC::PipeBarrier<PIPE_V>();
209	                AscendC::Add(tmpFp32Local_, tmpFp32Local_, maskFp32, rowLength);
210	            }
211	            maskInQueue_.FreeTensor(maskInLocal_);
212	        }
213	
214	        // Softmax step 1: find max
215	        AscendC::ReduceMax<float>(maxLocal_, tmpFp32Local_, reduceLocal_, rowLength);
216	        AscendC::PipeBarrier<PIPE_ALL>();
217	        float rowMax = maxLocal_.GetValue(0);
218	        AscendC::PipeBarrier<PIPE_ALL>();
219	
220	        // Softmax step 2: subtract max (broadcast)
221	        AscendC::Duplicate(broadcastLocal_, rowMax, rowLength);
222	        AscendC::PipeBarrier<PIPE_V>();
223	        AscendC::Sub(tmpFp32Local_, tmpFp32Local_, broadcastLocal_, rowLength);
224	
225	        // Softmax step 3: exp
226	        AscendC::Exp(tmpFp32Local_, tmpFp32Local_, rowLength);
227	        AscendC::PipeBarrier<PIPE_V>();
228	
229	        // Softmax step 4: sum
230	        AscendC::ReduceSum<float>(sumLocal_, tmpFp32Local_, reduceLocal_, rowLength);
231	        AscendC::PipeBarrier<PIPE_ALL>();
232	        float rowSum = sumLocal_.GetValue(0);
233	        AscendC::PipeBarrier<PIPE_ALL>();
234	
235	        // Softmax step 5: divide by sum (broadcast)
236	        AscendC::Duplicate(broadcastLocal_, rowSum, rowLength);
237	        AscendC::PipeBarrier<PIPE_V>();
238	        AscendC::Div(tmpFp32Local_, tmpFp32Local_, broadcastLocal_, rowLength);
239	
240	        // Cast back to output dtype
241	        if constexpr (std::is_same_v<dataType, float>) {
242	            AscendC::DataCopy(outLocal_.template ReinterpretCast<float>(), tmpFp32Local_, rowLength);
243	        } else {
244	            AscendC::Cast(outLocal_, tmpFp32Local_, OutputRoundModeHelper<dataType>(), rowLength);
245	        }
246	        AscendC::PipeBarrier<PIPE_V>();
247	
248	        xInQueue_.FreeTensor(xInLocal_);
249	        biasInQueue_.FreeTensor(biasInLocal_);
250	        outQueue_.EnQue(outLocal_);
251	    }
252	
253	    __aicore__ inline void ProcessRow(int rowIdx)
254	    {
255	        CopyInRow(rowIdx);
256	        ComputeRow();
257	        CopyOutRow(rowIdx);
258	    }
